'use strict';

const { Resource } = require('./Resource');

class Account extends Resource {
    user() {
        return this._client.get('user');
    }

    wallets() {
        return this._client.get('wallets');
    }

    transactions() {
        return this._client.get('transactions');
    }

    transaction(reference) {
        return this._client.get('transactions/' + encodeURIComponent(reference));
    }
}

module.exports = { Account };
